CREATE TYPE public.app_role AS ENUM ('admin', 'user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role_read ON public.user_roles FOR SELECT TO authenticated USING(user_id = auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated, service_role;
CREATE TABLE public.florist_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100), phone text NOT NULL CHECK(length(phone) BETWEEN 5 AND 40), message text NOT NULL CHECK(length(message) BETWEEN 1 AND 2000), status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','processing','done')), consent boolean NOT NULL CHECK(consent = true));
GRANT INSERT ON public.florist_requests TO anon, authenticated;
GRANT SELECT, UPDATE, DELETE ON public.florist_requests TO authenticated;
GRANT ALL ON public.florist_requests TO service_role;
ALTER TABLE public.florist_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY request_submit ON public.florist_requests FOR INSERT TO anon, authenticated WITH CHECK(status = 'new' AND consent = true);
CREATE POLICY admin_read_requests ON public.florist_requests FOR SELECT TO authenticated USING(public.has_role(auth.uid(), 'admin'));
CREATE POLICY admin_update_requests ON public.florist_requests FOR UPDATE TO authenticated USING(public.has_role(auth.uid(), 'admin')) WITH CHECK(public.has_role(auth.uid(), 'admin'));
CREATE POLICY admin_delete_requests ON public.florist_requests FOR DELETE TO authenticated USING(public.has_role(auth.uid(), 'admin'));